let currentViewMode = 'list';
let currentFilters = {
  role: 'All',
  engagement: 'All',
  account: 'All',
  search: ''
};

// Initialize
document.addEventListener('DOMContentLoaded', function() {
  setupEventListeners();
  renderContacts();
});

function setupEventListeners() {
  // View mode toggle
  document.querySelectorAll('.view-mode-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.view-mode-btn').forEach(b => b.classList.remove('active'));
      this.classList.add('active');
      currentViewMode = this.dataset.value;
      toggleViewMode();
      renderContacts();
    });
  });

  // Filter changes
  document.getElementById('roleFilter').addEventListener('change', function() {
    currentFilters.role = this.value;
    renderContacts();
  });

  document.getElementById('engagementFilter').addEventListener('change', function() {
    currentFilters.engagement = this.value;
    renderContacts();
  });

  document.getElementById('accountFilter').addEventListener('change', function() {
    currentFilters.account = this.value;
    renderContacts();
  });

  // Search inputs
  document.getElementById('listSearchInput').addEventListener('input', function() {
    currentFilters.search = this.value;
    debounceRender();
  });

  document.getElementById('searchInput').addEventListener('input', function() {
    currentFilters.search = this.value;
    debounceRender();
  });

  // Refresh button
  document.getElementById('refreshBtn').addEventListener('click', function() {
    renderContacts();
  });
}

let debounceTimeout;
function debounceRender() {
  clearTimeout(debounceTimeout);
  debounceTimeout = setTimeout(() => {
    renderContacts();
  }, 500);
}

function toggleViewMode() {
  const listView = document.getElementById('listView');
  const groupedView = document.getElementById('groupedView');
  const listSearchContainer = document.getElementById('listSearchContainer');
  const accountFilterContainer = document.getElementById('accountFilterContainer');
  const searchContainer = document.getElementById('searchContainer');

  if (currentViewMode === 'list') {
    listView.style.display = 'block';
    groupedView.style.display = 'none';
    listSearchContainer.style.display = 'block';
    accountFilterContainer.style.display = 'block';
    searchContainer.style.display = 'none';
  } else {
    listView.style.display = 'none';
    groupedView.style.display = 'block';
    listSearchContainer.style.display = 'none';
    accountFilterContainer.style.display = 'none';
    searchContainer.style.display = 'block';
  }
}

function filterContacts() {
  return mockContacts.filter(contact => {
    // Role filter
    if (currentFilters.role !== 'All' && contact.contactRole !== currentFilters.role) {
      return false;
    }

    // Engagement filter
    if (currentFilters.engagement !== 'All' && contact.engagementLevel !== currentFilters.engagement) {
      return false;
    }

    // Account filter (only for list view)
    if (currentViewMode === 'list' && currentFilters.account !== 'All' && contact.accountName !== currentFilters.account) {
      return false;
    }

    // Search filter
    if (currentFilters.search) {
      const searchLower = currentFilters.search.toLowerCase();
      const nameMatch = contact.fullName.toLowerCase().includes(searchLower);
      const emailMatch = contact.email && contact.email.toLowerCase().includes(searchLower);
      if (!nameMatch && !emailMatch) {
        return false;
      }
    }

    return true;
  });
}

function renderContacts() {
  const filteredContacts = filterContacts();

  if (currentViewMode === 'list') {
    renderListView(filteredContacts);
  } else {
    renderGroupedView(filteredContacts);
  }
}

function renderListView(contacts) {
  const contactsList = document.getElementById('contactsList');
  const noContactsMessage = document.getElementById('noContactsMessage');

  if (contacts.length === 0) {
    contactsList.innerHTML = '';
    noContactsMessage.style.display = 'block';
    return;
  }

  noContactsMessage.style.display = 'none';
  contactsList.innerHTML = contacts.map(contact => createContactCard(contact)).join('');
  attachContactCardListeners();
}

function renderGroupedView(contacts) {
  const accountGroupsList = document.getElementById('accountGroupsList');
  const noGroupsMessage = document.getElementById('noGroupsMessage');

  // Group contacts by account
  const grouped = {};
  contacts.forEach(contact => {
    if (!grouped[contact.accountId]) {
      grouped[contact.accountId] = {
        accountId: contact.accountId,
        accountName: contact.accountName,
        contacts: []
      };
    }
    grouped[contact.accountId].contacts.push(contact);
  });

  const groups = Object.values(grouped);

  if (groups.length === 0) {
    accountGroupsList.innerHTML = '';
    noGroupsMessage.style.display = 'block';
    return;
  }

  noGroupsMessage.style.display = 'none';
  accountGroupsList.innerHTML = groups.map(group => createAccountGroup(group)).join('');
  attachContactCardListeners();
}

function createContactCard(contact) {
  return `
    <div class="slds-col slds-size_1-of-1 slds-medium-size_1-of-2 slds-large-size_1-of-3">
      <div class="contact-card" data-id="${contact.contactId}">
        <div class="card-header">
          <h3 class="card-title">${contact.fullName}</h3>
          ${contact.engagementLevel ? `<span class="slds-badge">${contact.engagementLevel}</span>` : ''}
        </div>
        <div class="card-body">
          <div class="card-row">
            <span class="field-label">Title:</span>
            <span class="field-value">${contact.title || ''}</span>
          </div>
          <div class="card-row">
            <span class="field-label">Role:</span>
            <span class="field-value">${contact.contactRole || ''}</span>
          </div>
          ${currentViewMode === 'list' ? `
          <div class="card-row">
            <span class="field-label">Account:</span>
            <span class="field-value account-link" data-account-id="${contact.accountId}">${contact.accountName}</span>
          </div>
          ` : ''}
          <div class="card-row">
            <span class="field-label">Email:</span>
            <span class="field-value">
              ${contact.email ? `<a href="mailto:${contact.email}" class="action-link" onclick="event.stopPropagation()">${contact.email}</a>` : ''}
            </span>
          </div>
          <div class="card-row">
            <span class="field-label">Phone:</span>
            <span class="field-value">
              ${contact.phone ? `<a href="tel:${contact.phone}" class="action-link" onclick="event.stopPropagation()">${contact.phone}</a>` : ''}
            </span>
          </div>
          <div class="card-row">
            <span class="field-label">Preferred Method:</span>
            <span class="field-value">${contact.preferredContactMethod || ''}</span>
          </div>
          ${contact.linkedInProfile ? `
          <div class="card-actions">
            <button class="slds-button slds-button_outline-brand slds-m-top_small" data-linkedin="${contact.linkedInProfile}" onclick="event.stopPropagation(); window.open('${contact.linkedInProfile}', '_blank')">
              <svg class="slds-button__icon slds-button__icon_left" aria-hidden="true">
                <use xlink:href="/assets/icons/utility-sprite/svg/symbols.svg#socialshare"></use>
              </svg>
              View LinkedIn
            </button>
          </div>
          ` : ''}
        </div>
      </div>
    </div>
  `;
}

function createAccountGroup(group) {
  return `
    <div class="account-group slds-m-bottom_large">
      <div class="account-group-header">
        <h2 class="account-group-title" data-account-id="${group.accountId}">${group.accountName}</h2>
        <span class="slds-badge">${group.contacts.length}</span>
      </div>
      <div class="slds-grid slds-wrap slds-gutters">
        ${group.contacts.map(contact => createContactCard(contact)).join('')}
      </div>
    </div>
  `;
}

function attachContactCardListeners() {
  // Contact card clicks
  document.querySelectorAll('.contact-card').forEach(card => {
    card.addEventListener('click', function() {
      const contactId = this.dataset.id;
      console.log('Navigate to contact:', contactId);
    });
  });

  // Account link clicks
  document.querySelectorAll('.account-link, .account-group-title').forEach(link => {
    link.addEventListener('click', function(e) {
      e.stopPropagation();
      const accountId = this.dataset.accountId;
      console.log('Navigate to account:', accountId);
    });
  });
}

preview_css:
/* Contact Card Styles */
.contact-card {
    background: #ffffff;
    border: 1px solid #dddbda;
    border-radius: 4px;
    padding: 1rem;
    margin-bottom: 1rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.contact-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
    transform: translateY(-2px);
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dddbda;
}

.card-title {
    font-size: 1rem;
    font-weight: bold;
    color: #080707;
    margin: 0;
    flex: 1;
}

.card-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.card-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.875rem;
}

.field-label {
    color: #706e6b;
    font-weight: 500;
}

.field-value {
    color: #080707;
    text-align: right;
}

.action-link {
    color: #0176d3;
    text-decoration: none;
}

.action-link:hover {
    text-decoration: underline;
}

.account-link {
    color: #0176d3;
    cursor: pointer;
}

.account-link:hover {
    text-decoration: underline;
}

.card-actions {
    margin-top: 0.5rem;
    padding-top: 0.5rem;
    border-top: 1px solid #dddbda;
}

/* Account Group Styles */
.account-group {
    background: #fafaf9;
    border: 1px solid #dddbda;
    border-radius: 4px;
    padding: 1rem;
}

.account-group-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding-bottom: 0.75rem;
    border-bottom: 2px solid #dddbda;
}

.account-group-title {
    font-size: 1.25rem;
    font-weight: bold;
    color: #080707;
    margin: 0;
    cursor: pointer;
}

.account-group-title:hover {
    color: #0176d3;
    text-decoration: underline;
}

/* View mode button active state */
.view-mode-btn.active {
    background-color: #0176d3;
    color: #ffffff;
    border-color: #0176d3;
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .card-title {
        font-size: 0.9375rem;
    }

    .account-group-title {
        font-size: 1.125rem;
    }
}
